def AQ(n, stem, opts, a, why):
    html = mc(f'a{n}', ' '.join(stem), opts, a, why)
    S(f's-a{n}', f'שאלה נ.{n}', f'שאלה נ.{n}', f'<div class="mcwide">{html}</div>', kick='חלק 10 · שאלה')


def AS(n, letter, sol, ans, note, tl=None, split=None, wide=False):
    Q(f'sa{n}', f'פתרון נ.{n}', f'תשובה {letter}', [], sol, ans, note, tl=tl, split=split, wide=wide, kick='חלק 10 · פתרון מלא')


