ALTS = '<ul class="alts">' + ''.join(f'<li><b dir="ltr">{a}.</b> {b}</li>' for a, b in [('I', '20,000 ש״ח לשנה במשך 10 שנים. התשלום הראשון היום.'), ('II', '150,000 ש״ח היום.'), ('III', '60,000 ש״ח בעוד שנה, ו-110,000 ש״ח בעוד 5 שנים.'), ('IV', '260,000 ש״ח בעוד 7 שנים.')]) + '</ul>'
